lesson.snippet:
terraform {
  required_version = ">= 1.11"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 6.0" }
  }
}
provider "aws" { region = var.region }

variable "environment" {
  type = string
  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be dev, staging or prod"
  }
}

data "aws_caller_identity" "me" {}            # read-only lookup

resource "aws_ecr_repository" "app" {
  name = "ediscovery-agent-${var.environment}"
  lifecycle { prevent_destroy = true }        # plan fails instead of destroying
}
output "repo_url" { value = aws_ecr_repository.app.repository_url }

terraform {
  backend "s3" {
    bucket       = "isa-tfstate-prod-eu-central-1"
    key          = "ediscovery-agent/terraform.tfstate"
    region       = "eu-central-1"
    encrypt      = true
    kms_key_id   = "alias/tfstate"
    use_lockfile = true   # S3-native lock, writes <key>.tflock
  }
}

# Read a secret at run time; never written to state or plan
ephemeral "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
}

resource "aws_db_instance" "main" {
  # ...
  password_wo         = ephemeral.aws_secretsmanager_secret_version.db.secret_string
  password_wo_version = 1   # bump to resend the write-only value
}

# modules/fargate-service/main.tf (excerpt)
resource "aws_ecr_repository" "this" {
  name                 = var.name
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration { scan_on_push = true }
}
resource "aws_cloudwatch_log_group" "this" {
  name              = "/ecs/${var.name}"
  retention_in_days = var.log_retention_days   # default 90, never "never"
}
resource "aws_ecs_task_definition" "this" {
  family                   = var.name
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = var.cpu            # "512"
  memory                   = var.memory         # "1024"
  execution_role_arn       = var.execution_role_arn
  task_role_arn            = var.task_role_arn
  container_definitions = jsonencode([{
    name = var.name, image = "${aws_ecr_repository.this.repository_url}:${var.image_tag}",
    logConfiguration = { logDriver = "awslogs", options = {
      "awslogs-group" = aws_cloudwatch_log_group.this.name,
      "awslogs-region" = var.region, "awslogs-stream-prefix" = "ecs" } } }])
}

import {
  to = aws_s3_bucket.docs
  id = "firm-a-privileged-docs"     # then: terraform plan -generate-config-out=gen.tf
}

moved {
  from = aws_ecs_service.app
  to   = module.svc.aws_ecs_service.this   # rename in state, no destroy
}

removed {
  from = aws_cloudwatch_log_group.legacy
  lifecycle { destroy = false }     # forget it, keep the logs
}

# CI (PR):    terraform plan -out=tfplan -detailed-exitcode
#             exit 0 = no changes, 1 = error, 2 = changes to review
# CD (merge): terraform apply tfplan   # fails if state moved since the plan

{ "Version": "2012-10-17",
  "Statement": [{
    "Sid": "TrustEcsTasksOnlyFromThisAccount",
    "Effect": "Allow",
    "Principal": { "Service": "ecs-tasks.amazonaws.com" },
    "Action": "sts:AssumeRole",
    "Condition": {
      "StringEquals": { "aws:SourceAccount": "222222222222" },
      "ArnLike":      { "aws:SourceArn": "arn:aws:ecs:eu-central-1:222222222222:*" }
    }
  }]
}

// task role permissions: one matter prefix, one model
{ "Version": "2012-10-17",
  "Statement": [
    { "Effect": "Allow", "Action": ["s3:GetObject"],
      "Resource": "arn:aws:s3:::firm-a-privileged-docs/matter-2291/*" },
    { "Effect": "Allow", "Action": ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"],
      "Resource": "arn:aws:bedrock:eu-central-1::foundation-model/anthropic.*" }
  ]
}
